mapper.select:
SELECT ts.*, su.name as username, cmd.cmdNum, IFNULL(sftp.sftpNum, 0) sftpNum FROM terminal_session ts LEFT JOIN sys_user su ON ts.user_id = su.id LEFT JOIN ( SELECT uuid, ( count( 1 ) - 1 ) AS cmdNum FROM terminal_cmd GROUP BY uuid ) cmd ON cmd.uuid = ts.uuid LEFT JOIN ( SELECT uuid, count( 1 ) AS sftpNum FROM terminal_sftp_log GROUP BY uuid ) sftp ON sftp.uuid = ts.uuid
ts.protocol = #{params.protocol}
AND locate(#{params.loginUser} , ts.login_user)
AND ts.status = #{params.state}
AND locate(#{params.uuid} , ts.uuid)
AND locate(#{params.remoteAddr} , ts.remote_addr)
AND locate(#{params.host} , ts.host)
AND ts.start_time >= #{params.startTime}
AND ts.end_time <= #{params.endTime}
AND ts.user_id = #{params.userId}
AND locate(#{params.username} , su.username)
AND locate(#{params.remoteAddr} , ts.remote_addr)
ORDER BY ts.id DESC
